-- Baseline from severe_equipment_assets; metadata only, zero business records.
BEGIN;
CREATE TABLE IF NOT EXISTS app_menu_groups (
 "group_key" text NOT NULL,
 "group_label" text NOT NULL,
 "icon" text,
 "sort_order" integer NOT NULL DEFAULT 0,
 CONSTRAINT "app_menu_groups_pkey" PRIMARY KEY (group_key)
);
CREATE TABLE IF NOT EXISTS app_modules (
 "module_id" text NOT NULL,
 "group_key" text NOT NULL,
 "module_name" text NOT NULL,
 "route_path" text NOT NULL,
 "page_title" text,
 "page_subtitle" text,
 "icon" text,
 "stats" jsonb NOT NULL DEFAULT '[]'::jsonb,
 "tabs" jsonb NOT NULL DEFAULT '[]'::jsonb,
 "process_steps" jsonb NOT NULL DEFAULT '[]'::jsonb,
 "sort_order" integer NOT NULL DEFAULT 0,
 "enabled" boolean NOT NULL DEFAULT true,
 "created_at" timestamp with time zone NOT NULL DEFAULT now(),
 "updated_at" timestamp with time zone NOT NULL DEFAULT now(),
 CONSTRAINT "app_modules_group_key_fkey" FOREIGN KEY (group_key) REFERENCES app_menu_groups(group_key),
 CONSTRAINT "app_modules_pkey" PRIMARY KEY (module_id)
);
CREATE TABLE IF NOT EXISTS app_module_columns (
 "id" uuid NOT NULL DEFAULT gen_random_uuid(),
 "module_id" text NOT NULL,
 "column_key" text NOT NULL,
 "column_label" text NOT NULL,
 "data_type" text NOT NULL DEFAULT 'text'::text,
 "sort_order" integer NOT NULL,
 CONSTRAINT "app_module_columns_module_id_column_key_key" UNIQUE (module_id, column_key),
 CONSTRAINT "app_module_columns_module_id_fkey" FOREIGN KEY (module_id) REFERENCES app_modules(module_id) ON DELETE CASCADE,
 CONSTRAINT "app_module_columns_pkey" PRIMARY KEY (id)
);
CREATE TABLE IF NOT EXISTS app_module_fields (
 "id" uuid NOT NULL DEFAULT gen_random_uuid(),
 "module_id" text NOT NULL,
 "field_key" text NOT NULL,
 "field_label" text NOT NULL,
 "field_type" text NOT NULL,
 "db_type" text NOT NULL,
 "sample_value" text,
 "options" jsonb NOT NULL DEFAULT '[]'::jsonb,
 "required" boolean NOT NULL DEFAULT false,
 "sort_order" integer NOT NULL,
 CONSTRAINT "app_module_fields_module_id_field_key_key" UNIQUE (module_id, field_key),
 CONSTRAINT "app_module_fields_module_id_fkey" FOREIGN KEY (module_id) REFERENCES app_modules(module_id) ON DELETE CASCADE,
 CONSTRAINT "app_module_fields_pkey" PRIMARY KEY (id)
);
CREATE TABLE IF NOT EXISTS app_records (
 "id" uuid NOT NULL DEFAULT gen_random_uuid(),
 "module_id" text NOT NULL,
 "record_no" text NOT NULL,
 "title" text NOT NULL,
 "status" text NOT NULL DEFAULT 'draft'::text,
 "project_name" text,
 "payload" jsonb NOT NULL DEFAULT '{}'::jsonb,
 "created_at" timestamp with time zone NOT NULL DEFAULT now(),
 "updated_at" timestamp with time zone NOT NULL DEFAULT now(),
 "created_by" text,
 "updated_by" text,
 "deleted_at" timestamp with time zone,
 "is_test" boolean NOT NULL DEFAULT false,
 CONSTRAINT "app_records_module_id_fkey" FOREIGN KEY (module_id) REFERENCES app_modules(module_id),
 CONSTRAINT "app_records_module_id_record_no_key" UNIQUE (module_id, record_no),
 CONSTRAINT "app_records_pkey" PRIMARY KEY (id)
);
CREATE TABLE IF NOT EXISTS app_schema_migrations(version text PRIMARY KEY,applied_at timestamptz NOT NULL DEFAULT now());
COMMIT;
